head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90900";
scwin.id_button = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.id_button = $c.util.getComponent('id_button');
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90900.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isuNm", fn: function () { return String((dma_pageContext.get("isuNm") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const apct_tel_no = $c.util.getComponent('ipt_apctTelNo').getValue();
        const apct_fax_no = $c.util.getComponent('ipt_apctFaxNo').getValue();
        const encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail').getValue();
        const encryp_cellphone_no = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
        const arrayTel = apct_tel_no.split("-");
        const arrayFax = apct_fax_no.split("-");
        const arrayEmail = encryp_apct_email.split("@");
        const arrayHp = encryp_cellphone_no.split("-");
        for (let i = 0; i < arrayTel.length; i++) {
            $("#apct_tel_no_" + (i + 1)).val(arrayTel[i]);
        }
        for (let i = 0; i < arrayFax.length; i++) {
            $("#apct_fax_no_" + (i + 1)).val(arrayFax[i]);
        }
        for (let i = 0; i < arrayEmail.length; i++) {
            $("#encryp_apct_email_" + (i + 1)).val(arrayEmail[i]);
        }
        for (let i = 0; i < arrayHp.length; i++) {
            $("#encryp_cellphone_no_" + (i + 1)).val(arrayHp[i]);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_stdCdApctTpCd_onclick
 * @description 「4」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stdCdApctTpCd_onclick = function(e){
    try {
        scwin.setInsurInfo(4)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.ipt_stdCdApctTpCd_onclick' }); }
};

