/**
 * @method
 * @name ipt_apctNm_onblur
 * @description ipt_apctNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_apctNm_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.chk_chrg_nm(selfVar, 20, '신청인 이름');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90900.ipt_apctNm_onblur' }); }
};

/**
 * @method
 * @name ipt_apctNm_onkeypress
 * @description ipt_apctNm onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_apctNm_onkeypress = function(e){
    try {
        fn_etcNumNotCheck()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.ipt_apctNm_onkeypress' }); }
};

/**
 * @method
 * @name ipt_encrypApctEmail1_onkeydown
 * @description ipt_encrypApctEmail1 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypApctEmail1_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.ipt_encrypApctEmail1_onkeydown' }); }
};

/**
 * @method
 * @name ipt_encrypApctEmail2_onkeydown
 * @description ipt_encrypApctEmail2 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypApctEmail2_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.ipt_encrypApctEmail2_onkeydown' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90900.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_closeWin_onclick
 * @description btn_closeWin 클릭 이벤트
